// ============================================================
// DETERMINISTIC UUID
//
// Qdrant accepts UUID point IDs.
// We generate the same UUID for the same
// source + chunk index.
//
// This makes ingestion idempotent.
// ============================================================

function createPointId(source, chunkIndex) {

function createPointId(source, chunkIndex) {

    const hash = crypto
        .createHash("sha256")
        .update(
            `${source}:${chunkIndex}`
        )
        .digest();

    // Take first 16 bytes.
    const bytes = Buffer.from(
        hash.subarray(0, 16)
    );

    // Set UUID version = 4.
    bytes[6] =
        (bytes[6] & 0x0f) | 0x40;

    // Set UUID variant.
    bytes[8] =
        (bytes[8] & 0x3f) | 0x80;

    const hex =
        bytes.toString("hex");

const hex =
        bytes.toString("hex");

    return [
        hex.substring(0, 8),
        hex.substring(8, 12),
        hex.substring(12, 16),
        hex.substring(16, 20),
        hex.substring(20, 32)
    ].join("-");
}


