                    `Gemini embedding failed after ` +
                    `${retries} attempts. ` +
                    `Last error: ${error.message}`
                );
            }

            // Respect server-provided retry delay
            // when available.
            const retryAfter =
                getRetryAfterMs(error);

            let delay;

            if (retryAfter) {

if (retryAfter) {

                delay = Math.min(
                    retryAfter,
                    MAX_BACKOFF_MS
                );

            } else {

                const exponential =
                    INITIAL_BACKOFF_MS *
                    Math.pow(
                        2,
                        attempt - 1
                    );

const capped =
                    Math.min(
                        exponential,
                        MAX_BACKOFF_MS
                    );

                // Add random jitter.
                const jitter =
                    Math.random() * 1000;

                delay =
                    capped + jitter;
            }

console.warn(
                `[WARN] Gemini request failed. ` +
                `Attempt ${attempt}/${retries}. ` +
                `Retrying in ${Math.round(delay / 1000)}s...`
            );

            console.warn(
                `[WARN] ${error.message}`
            );

            await sleep(delay);
        }
    }

    throw new Error(
        "Unexpected embedding failure."
    );
}

