        // ----------------------------------------------------

        for (
            const point of points
        ) {

completed.add(
                point.id
            );
        }


        state.inProgress.completedIds =
            Array.from(completed);


        saveState(state);


        console.log(
            `[CHECKPOINT] ` +
            `${completed.size}/${chunks.length} ` +
            `chunks completed.`
        );
    }

// --------------------------------------------------------
    // VERIFY ALL CHUNKS COMPLETED
    // --------------------------------------------------------

    if (
        completed.size !==
        chunks.length
    ) {

        throw new Error(
            `File processing incomplete for ${source}.`
        );
    }

// --------------------------------------------------------
    // DELETE OLD CHUNKS
    //
    // Do this AFTER new chunks have been uploaded.
    // This prevents losing the old version if
    // embedding fails halfway through.
    // --------------------------------------------------------

    if (
        previous &&
        previous.chunkIds
    ) {

        const newIds =
            new Set(chunkIds);

const obsoleteIds =
            previous.chunkIds.filter(
                id =>
                    !newIds.has(id)
            );


        if (
            obsoleteIds.length > 0
        ) {

            await deletePoints(
                qdrant,
                obsoleteIds
            );
        }
    }


    // --------------------------------------------------------
    // FILE COMPLETE
    // --------------------------------------------------------

    state.files[source] = {

state.files[source] = {

        hash:
            fileHash,

        status:
            "completed",

        chunkIds,

        chunkCount:
            chunks.length,

        updatedAt:
            new Date().toISOString()
    };


    state.inProgress = null;


    saveState(state);


    console.log(
        `[DONE] ${source}`
    );
